import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import EventSalesFilterForm from './EventSalesFilterForm';
import EventSalesInputForm  from './EventSalesInputForm';
import EventSalesResult     from './EventSalesResult';
import { phonePlans }       from '../config/phonePlanConfig';
import { defaultEventConfig } from '../config/eventConfig';

export default function EventSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    others: '',
    deviceModel: '',
    deviceVariant: '',
    discountType: '',
    partialPayment: 0,
    subsidyAmount: 0,
    installments: 24,
    pensionApply: '',    // 기초연금 수급 여부
  });
  const [result, setResult] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');

  // 월 이자율
  const monthlyRate = 0.059 / 12;

  // 필터 변경 핸들러
  const handleFilterChange = (field, value) => {
    setValues(prev => ({
      ...prev,
      [field]: value,
      ...(field === 'planId'
        ? {
            planCost: phonePlans.find(p => p.id === value)?.monthlyFee || 0,
            others: phonePlans.find(p => p.id === value)?.others || '',
          }
        : {}),
      ...(field === 'dataFilter' ? { category: '', planId: '', planCost: 0, others: '' } : {}),
      ...(field === 'category'   ? { planId: '', planCost: 0, others: '' } : {}),
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  // 입력 변경 핸들러
  const handleInputChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: ['partialPayment', 'subsidyAmount', 'installments'].includes(name)
        ? Number(value)
        : value,
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  // 계산 가능 여부 (시니어는 기초연금 선택 필수)
  const isSenior = values.category === '5G 시니어 (만 65세 이상)';
  const hasPension = values.pensionApply === 'yes' || values.pensionApply === 'no';
  const canCalc =
    values.planCost > 0 &&
    values.deviceModel !== '' &&
    values.deviceVariant !== '' &&
    values.discountType !== '' &&
    (!isSenior || hasPension);

  // 계산 로직
  const handleCalculate = () => {
    if (!canCalc) return;
    const {
      planCost,
      deviceModel,
      deviceVariant,
      discountType,
      partialPayment,
      subsidyAmount,
      installments,
    } = values;

    // 기본 원금 추출
    const basePrincipal =
      defaultEventConfig.devices.find(d => d.id === deviceModel)?.variants
        .find(v => v.id === deviceVariant)?.price || 0;
    const principalContract = basePrincipal - partialPayment;
    const principalSubsidy = principalContract - subsidyAmount;

    // 요금할인 시나리오
    const planContract = Math.round(planCost * 0.75);
    const deviceContract = installments
      ? Math.ceil(
          (principalContract * monthlyRate) /
            (1 - Math.pow(1 + monthlyRate, -installments))
        )
      : 0;
    const totalContract = planContract + deviceContract;

    // 공시지원금 시나리오
    const planSubsidy = planCost;
    const deviceSubsidy = installments
      ? Math.ceil(
          (principalSubsidy * monthlyRate) /
            (1 - Math.pow(1 + monthlyRate, -installments))
        )
      : 0;
    const totalSubsidy = planSubsidy + deviceSubsidy;

    // 사용자 선택 시나리오
    const monthlyPlanCost =
      discountType === 'contract' ? planContract : planSubsidy;
    const deviceInstallment =
      discountType === 'contract' ? deviceContract : deviceSubsidy;
    const totalPayment =
      discountType === 'contract' ? totalContract : totalSubsidy;

    // 절감액 및 추천
    const savings =
      discountType === 'contract'
        ? totalSubsidy - totalContract
        : totalContract - totalSubsidy;
    const recommended =
      totalContract < totalSubsidy ? '요금할인' : '공시 지원금';

    setResult({ monthlyPlanCost, deviceInstallment, totalPayment, savings });
    setRecommendedDiscount(recommended);
  };

  return (
    <div className="flex justify-center bg-gray-100 p-4 min-h-screen items-start pt-8">
      <div className="w-full max-w-lg bg-white rounded-lg shadow-lg p-6">
        <h1 className="text-2xl font-bold mb-2 text-center">KT 이벤트 계산기</h1>
        <p className="text-center text-red-600 text-sm mb-4">
          주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.
        </p>
        <EventSalesFilterForm
          values={values}
          onChange={handleFilterChange}
          phonePlans={phonePlans}
        />
        <EventSalesInputForm
          values={values}
          onChange={handleInputChange}
          defaultConfig={defaultEventConfig}
          recommendedDiscount={recommendedDiscount}
        />

        <button
          type="button"
          onClick={handleCalculate}
          disabled={!canCalc}
          className={`w-full py-2 rounded-lg mb-3 transition ${
            canCalc
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'bg-gray-300 text-gray-500 cursor-not-allowed'
          }`}
        >
          계산하기
        </button>

        {result && (
          <EventSalesResult
            monthlyPlanCost={result.monthlyPlanCost}
            deviceInstallment={result.deviceInstallment}
            totalPayment={result.totalPayment}
            savings={result.savings}
            discountType={values.discountType}
          />
        )}
        <button
          type="button"
          onClick={() => navigate('/')}
          className="w-full bg-gray-200 text-gray-700 py-2 rounded-lg mt-2"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
