import React from 'react';

export default function EventSalesResult({
  monthlyPlanCost,
  deviceInstallment,
  totalPayment,
  savings,
  discountType
}) {
  // 렌더링 전에 undefined 방어
  const mpc = monthlyPlanCost ?? 0;
  const di = deviceInstallment ?? 0;
  const tp = totalPayment ?? 0;
  const sv = savings ?? 0;

  const sign = sv > 0 ? '+' : sv < 0 ? '-' : '';
  const absSavings = Math.abs(sv);

  // subsidy 먼저 체크하여 공시 지원금 레이블 우선
  const label =
    discountType === 'subsidy'
      ? '공시 지원금 절감액'
      : discountType === 'contract'
        ? '요금할인 절감액'
        : '';

  return (
    <div className="bg-gray-100 p-4 rounded-lg space-y-2">
      <p className="text-lg">
        월 요금제: <strong>{mpc.toLocaleString()}원</strong>
      </p>
      <p className="text-lg">
        단말 할부 대금: <strong>{di.toLocaleString()}원</strong>
      </p>
      <p className="text-lg">
        월 총 납부 예상 금액: <strong>{tp.toLocaleString()}원</strong>
      </p>
      {label && (
        <p className={`text-lg ${sv >= 0 ? 'text-green-600' : 'text-red-600'}`}>
          {label}: {sign}{absSavings.toLocaleString()}원
        </p>
      )}
      <p className="mt-2 text-base font-bold text-red-500">
        경고! 본 견적은 대략적인 결과 값 입니다.
      </p>
    </div>
  );
}
